from second50_io import *

def latest(pattern):return max(R.glob(pattern),key=lambda p:int(p.stem.rsplit('_',1)[1]))

cpu_path=latest('SECOND50_OWN_FORMAL_CPU_ACTUAL_[0-9]*.json');cpu=json.loads(cpu_path.read_bytes());assert cpu['passed'] and cpu['closeout_ready'] and cpu['actual_source_count']==386
startup_path=latest('SECOND50_OWN_STARTUP_CPU_ACTUAL_[0-9]*.json');startup=json.loads(startup_path.read_bytes());assert startup['passed'] and startup['actual_saved_PPO_updates_positive'] and startup['own_checkpoint']['sha256']==cpu['own_checkpoint']['sha256']
trace_path=latest('SECOND50_FULL_TRAINING_TRACE_ACTUAL_[0-9]*.json');trace=json.loads(trace_path.read_bytes());assert trace['passed'] and trace['own_checkpoint_SHA']==cpu['own_checkpoint']['sha256']
collection_path=latest('SECOND50_OWN_FINAL_ACTUAL_COLLECTION_[0-9]*.json');collection=json.loads(collection_path.read_bytes());assert collection['passed'] and collection['own_checkpoint']['sha256']==cpu['own_checkpoint']['sha256']
own=cpu['own'];h=own['health'];segment=own['unique_completed_segment'][0];wall=segment['ended_epoch']-segment['started_epoch'];assert len(own['unique_completed_segment'])==1 and 1800<wall<1920 and own['actual_updates']*24==h['control_steps']==trace['actual_controls']==startup['actual_saved_trace_controls']
assert h['actual_physics_callbacks']==h['control_steps']*4 and own['actual_environment_steps']==h['control_steps']*20000
assert h['termination_reason_coverage_exact'] and h['truncation_reason_coverage_exact'] and not h['nonfinite_observed'] and h['stop_reason'] is None
info=next(x for x in collection['indices'] if x['path']==cpu['own_checkpoint']['path']);assert info['sha256']==cpu['own_checkpoint']['sha256']
out=save('SECOND50_FORMAL_FINAL_ACTUAL_REVIEW.json',dict(epoch=time.time(),passed=True,own_CPU_review=str(cpu_path),own_saved_PPO_startup_review=str(startup_path),complete_training_trace_review=str(trace_path),own_final_actual_collection=str(collection_path),own_checkpoint=dict(cpu['own_checkpoint'],bytes=info['bytes']),source_count=386,actual_snapshot_file_count=cpu['actual_snapshot_file_count'],own_PID=cpu['own_PID'],updates=own['actual_updates'],controls=h['control_steps'],environment_steps=own['actual_environment_steps'],callbacks=h['actual_physics_callbacks'],actor_tensors_changed=startup['actor_tensors_changed'],optimizer_step_delta_min=startup['optimizer_step_delta_min'],health=h,actual_load_learn_save_exit_seconds=wall,unique_completed_segment=own['unique_completed_segment'],time_out_and_route_overlap=h['termination_events_by_reason']['time_out']+h['termination_events_by_reason']['rough_route_boundary']-h['actual_truncation_reset_events'],closeout_ready=True,actual_parent_guardian_child_processes=cpu['actual_processes'],actual_fcntl_locks=cpu['locks'],actual_state=cpu['actual_state'],remaining_snapshot_seconds=cpu['remaining_snapshot_seconds'],same50_full_CPUCUDA_restore_and_episode_plus_one_actual_passed=True,non_PhysX_exact_resume=True,all_ordinary_and_original_false_preserved=True,candidate147_full_scope_decision_required_before_new_PPO_or70mm=True,no_automatic_third_same50_duration_only_block=True,not_qualified50mm_from_training_save_or_legacy_skill=True,no_GPU_budget_or_old_once_replay=True))
print(json.dumps(dict(report=str(out),updates=own['actual_updates'],controls=h['control_steps'],actual_seconds=wall,ordinary=h['ordinary_episode_reset_events'],checkpoint_SHA=cpu['own_checkpoint']['sha256'],overlap=h['termination_events_by_reason']['time_out']+h['termination_events_by_reason']['rough_route_boundary']-h['actual_truncation_reset_events'])))
